#include <iostream>
using namespace std;
char s[1010];
int main() {
    int n;
    cin >> n;
    cin >> s;
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if ('a' <= c && c <= 'z')
            cout << (char)(c - ('a' - 'A'));
        else if ('A' <= c && c <= 'Z')
            cout << (char)(c + ('a' - 'A'));
        else
            cout << '*';
    }
    cout << endl;
    return 0;
}
